templates.body:
{
  "format": "ankhimate-runtime",
  "context_version": {{context_version}},
  "name": "{{project.name}}",
  "fps": {{project.fps}},
  "bones": [
{{#each skeleton.bones}}    {"name":"{{name}}","parent":{{parent_index}},"length":{{round length 4}},"x":{{round x 4}},"y":{{round y 4}},"rotation":{{round rotation 4}},"scaleX":{{round scale_x 4}},"scaleY":{{round scale_y 4}},"shearX":{{round shear_x 4}},"shearY":{{round shear_y 4}},"inheritRotation":{{inherit_rotation}},"inheritScale":{{inherit_scale}},"inheritReflect":{{inherit_reflect}}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "slots": [
{{#each skeleton.slots}}    {"name":"{{name}}","bone":"{{bone}}","attachment":{{#if attachment}}"{{attachment}}"{{else}}null{{/if}},"color":"{{hex color}}","blend":"{{blend}}"}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "drawOrder": {{json skeleton.draw_order}},
  "defaultSkin": "{{skeleton.default_skin}}",
  "skins": [
{{#each skeleton.skins}}    {"name":"{{name}}","bones":{{json bones}},"constraints":{{json constraints}},"attachments":[
{{#each entries}}      {"slot":"{{slot}}","name":"{{name}}","attachment":{{json attachment}}}{{#unless @last}},{{/unless}}
{{/each}}    ]}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "constraints": [
{{#each skeleton.constraints}}    {{json this}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "constraintOrder": {{json skeleton.constraint_order}},
  "animations": {
{{#each animations}}    "{{name}}": {
      "duration": {{round duration 4}},
      "looping": {{looping}},
      "bones": [
{{#each bones}}        {"name":"{{name}}"{{#if translate}},"translate":{{json translate}}{{/if}}{{#if rotate}},"rotate":{{json rotate}}{{/if}}{{#if scale}},"scale":{{json scale}}{{/if}}{{#if shear}},"shear":{{json shear}}{{/if}}}{{#unless @last}},{{/unless}}
{{/each}}      ],
      "slots": {{json slots}},
      "deform": {{json deform}},
      "drawOrder": {{json draw_order}},
      "ik": {{json ik}},
      "transform": {{json transform}},
      "events": {{json events}}
    }{{#unless @last}},{{/unless}}
{{/each}}  },
  "atlas": {{#if atlas}}{"pages":{{json atlas.pages}},"regions":{{json atlas.regions}}}{{else}}null{{/if}}
}
